inline bool VerifyClientPayload(::flatbuffers::Verifier &verifier, const void *obj, ClientPayload type) {
  switch (type) {
    case ClientPayload_NONE: {
      return true;
    }
    case ClientPayload_StartAudioStream: {
      auto ptr = reinterpret_cast<const Pumpkin::Protocol::StartAudioStream *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ClientPayload_StopAudioStream: {
      auto ptr = reinterpret_cast<const Pumpkin::Protocol::StopAudioStream *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ClientPayload_PlayShow: {
      auto ptr = reinterpret_cast<const Pumpkin::Protocol::PlayShow *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ClientPayload_AudioChunk: {
      auto ptr = reinterpret_cast<const Pumpkin::Protocol::AudioChunk *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ClientPayload_ResetAudio: {
      auto ptr = reinterpret_cast<const Pumpkin::Protocol::ResetAudio *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ClientPayload_GetVolume: {
      auto ptr = reinterpret_cast<const Pumpkin::Protocol::GetVolume *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ClientPayload_AdjustVolume: {
      auto ptr = reinterpret_cast<const Pumpkin::Protocol::AdjustVolume *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

inline bool VerifyClientPayloadVector(::flatbuffers::Verifier &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<uint8_t> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyClientPayload(
        verifier,  values->Get(i), types->GetEnum<ClientPayload>(i))) {
      return false;
    }
  }
  return true;
}

